"""A tiny loader for INI-style configuration with typed values."""


def _coerce_value(value):
    if len(value) >= 2 and value[0] == value[-1] == '"':
        return value[1:-1]

    lowered = value.lower()
    if lowered == "true":
        return True
    if lowered == "false":
        return False

    try:
        return int(value)
    except ValueError:
        pass

    try:
        return float(value)
    except ValueError:
        return value


def parse_config(text):
    config = {"": {}}
    section = ""

    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line or line.startswith(("#", ";")):
            continue

        if line.startswith("[") and line.endswith("]"):
            section = line[1:-1].strip()
            config.setdefault(section, {})
            continue

        if "=" not in line:
            continue

        key, value = line.split("=", 1)
        config.setdefault(section, {})[key.strip()] = _coerce_value(value.strip())

    return config


def get(config, dotted, default=None):
    if "." in dotted:
        section, key = dotted.split(".", 1)
    else:
        section, key = "", dotted

    return config.get(section, {}).get(key, default)

